common=dict(measure_id='pfu-petits-revenus-plafond-vingt',affected_population="Foyers fiscalement domiciliés en France ; seuls revenus et gains effectivement soumis aux taux forfaitaires du 1 B de l'article 200 A. Plafond complet sous le seuil RFR par part de la tranche à 11 %, puis extinction progressive.",conditions_and_transition="RFR et parts de l'année imposée ; seuil dynamique du 197 ; faits générateurs à compter de l'entrée en vigueur proposée. Placements antérieurs éligibles pour leurs faits générateurs futurs ; droits des périodes antérieures protégés.",replacement_or_new_burdens="Pas de nouveau formulaire autonome. Calcul annuel par groupes homogènes et répartition des crédits : complexité administrative supplémentaire non chiffrée. Acomptes et taux sociaux maintenus ; pas de baisse immédiate garantie à la source.",source_quote=q,proposed_quote=paras[7])
effects=[dict(common,kind='tax_reduced',description="Plafond de charge française de 20 % et lissage au-delà du seuil, par crédit borné à l'impôt français restant.",before="PFU ordinaire 2026 : 12,8 % d'IR sur l'assiette du 200 A, plus 10,6 % de CSG, 0,5 % de CRDS et 7,5 % de solidarité sur leurs assiettes propres, soit 31,4 % lorsque les bases coïncident ; exceptions et exonérations autonomes.",after="Charge française plafonnée à 20 % de la fraction imposable sous le seuil, puis retrait de 0,50 € de crédit par euro de RFR excédentaire ; aucun crédit si le régime est déjà plus favorable ou si l'IR français restant est nul.",unit='percent'),dict(common,kind='complexity_added',description="Ajoute un calcul par groupes homogènes, une attribution des avantages fiscaux et un lissage annuel du crédit.",before="Calcul de l'impôt forfaitaire aux taux du 200 A et règles sociales distinctes, sans crédit de plafonnement selon le RFR de la même année.",after="Calcul des bases B, charges sociales T, IR attribuable I et crédit G, puis du retrait progressif lié au RFR ; aucun formulaire autonome ajouté, mais charge de calcul supplémentaire réelle.",unit='regime')]
row={k:s[k]for k in ['code_id','source_id','source_sha256','number']};row.update(status='rewrite_draft',proposed_xml=new,reason="Ajoute un plafond total de charge française de 20 % pour les revenus mobiliers forfaitaires des foyers sous le seuil indexé de la tranche IR à 11 %, puis un retrait progressif du crédit. Conserve intégralement les autres dispositions du projet, notamment la suppression du coefficient 1,25 et l'option globale rectifiable.",review_notes="Sources et notes des treize articles capturés lues intégralement ; corps 200 A antérieur conservé exactement hors ajout du C dans le 1. Le taux de 20 %, le seuil et le lissage de 0,50 sont le calibrage de ce projet, jamais un chiffrage attribué à David Lisnard. Le crédit ne rembourse pas d'impôt étranger, de charge sociale ni de revenu exonéré ; il est borné à l'IR français restant, avant l'imputation unique des avances. Formule et limites exposées dans NOTE.md ; coût national, réponses comportementales et effets sur les budgets publics non chiffrés. Aucun certificat technique ne vaut validation juridique indépendante. La contrelecture doit confirmer les modalités de répartition des crédits non affectables et les informations d'assurance-vie déjà disponibles pour éviter tout double compte.",benefit_review="Sont préservés intégralement l'option globale rectifiable du 2, l'abattement de 40 % des dividendes lorsqu'il relève du barème, les pertes légalement imputables, les exonérations du PEA et des placements spéciaux, les taux et abattements de l'assurance-vie, les crédits conventionnels et leur plafonnement, les dispenses d'acomptes, les droits à restitution et les règles de déductibilité de CSG. Aucun avantage futur recevable n'est fermé ; aucune fraction exonérée n'est réintroduite dans la base pour fabriquer un crédit. Les avances déjà versées sont imputées et, le cas échéant, restituées une seule fois.",substantive_impact=dict(version=1,classification='mixed',assessment="Le crédit réduit réellement l'IR français restant sur les revenus forfaitaires visés, en tenant compte des prélèvements sociaux effectivement dus sur la même fraction. Il ajoute un calcul annuel et un lissage : cet ajout est déclaré comme complexité, sans prétendre à un allègement net de toutes les obligations du code.",scope_limitations="Le plafond couvre l'IR et les trois prélèvements sociaux énumérés, pas l'impôt étranger, les revenus exonérés, les prélèvements libératoires autonomes ni l'impôt d'autres catégories. Le barème peut rester plus favorable et conserve son option globale. Aucune économie nationale, autofinancement ou compensation automatique de ressources locales n'est démontré.",new_burdens_review="Aucun taux ou prélèvement social nouveau, aucune inscription et aucun formulaire autonome ne sont créés. En revanche, le crédit ajoute un regroupement d'assiettes et une attribution des avantages fiscaux, dont le coût de traitement et de contrôle est inconnu. Les acomptes restent ceux du droit existant jusqu'à la régularisation annuelle.",effects=effects))
validate(row,s,required=True);pol=sha((P/'policy-coordinations.json').read_bytes());row['substantive_impact_certificate']=certificate(row,s,pol)
save('source.json',[s]);save('answer.json',[row]);save('policy.proposed.json',dict(active=False,authority='Décision explicite de l’auteur, transmise par le parent',not_attributed_to_lisnard=True,article='200 A, 1 C',rate_total=.20,smoothing_coefficient=.50,year='N, année des revenus et gains imposés',threshold='Nombre de parts N × limite supérieure de la tranche IR à 11 % du 197 pour la même année',base='Fractions effectivement imposables au 200 A 1 B, par groupes homogènes',foreign_tax='Exclu ; crédit conventionnel déduit avant calcul, sans remboursement nouveau',advances='Imputation unique après le crédit ; aucun taux de retenue modifié',fiscal_cost='Inconnu ; pas de promesse d’autofinancement ni de compensation de ressources locales'))
review=[]
for x in sources[1:]:
 n=x['number'];why={'117 quater':'Le V vise déjà le 1 ou le 2 du 200 A ; le nouveau C appartient au 1. Acompte 12,8 % et dispenses fondées sur N−2 maintenus, pas de promesse de débit immédiat à 20 %.','125 A':'Le V vise déjà le 1 ou le 2 du 200 A ; le C s’intègre au 1. Les régimes libératoires autonomes de solidarité et ETNC ne sont pas étendus au nouveau crédit.','125 D':'Les revenus étrangers entrant dans le forfait du 200 A bénéficient du C sans changer la collecte. Options libératoires historiques, délais, conventions et crédit étranger sont conservés.','154 quinquies':'Aucune CSG n’est remboursée par le crédit IR ; les règles de déduction de CSG, dont le barème, restent intégralement applicables.','L136-8':'Aucun taux social n’est modifié. CSG ordinaire mobilière 10,6 %, exceptions dont assurance-vie 9,2 %, taux de remplacement et baisse projetée sur salaires privés restent à leurs champs propres.'}[n]
 review.append(dict(number=n,source_id=x['source_id'],source_sha256=x['source_sha256'],source_notes_sha256=x['source_notes_sha256'],current_beforeimage_sha256=x['current_beforeimage_sha256'],action='no_change',reason=why))
save('coordinations-review.json',dict(whole_texts='source-all.json',new_proposals=1,unchanged_coordination_articles=review,no_cosmetic_rewrites=True))
